#!/bin/zsh
# Tests the widget, builds it, and installs or updates both LaunchAgents (daily and weekly),
# which start it now and at every login. Safe to run as often as you like. See README.md.
set -e
cd "$(dirname "$0")"

if ! command -v swiftc >/dev/null || ! swiftc --version >/dev/null 2>&1; then
  echo "The Swift compiler isn't installed. Run this, then try again:  xcode-select --install"
  exit 1
fi

./test.sh

# The widget finds its location files through this path, so rerun this script if you move the folder.
cat > BuildPaths.swift <<SWIFT
// Generated by build.sh; do not edit.
let projectDirectory = "$PWD"
SWIFT

# Build to a temp file and move it into place, so the running copies aren't overwritten mid-use.
BIN="$HOME/.local/bin/checklist-widget"
mkdir -p "$HOME/.local/bin" "$HOME/Library/LaunchAgents" "$HOME/Library/Logs"
swiftc -swift-version 5 -O -parse-as-library ChecklistWidget.swift Core.swift BuildPaths.swift -o "$BIN.new"
mv -f "$BIN.new" "$BIN"
echo "built $BIN"

# install_agent <label> <log name> [argument]
install_agent() {
  local label="com.$(id -un).$1" log="$HOME/Library/Logs/$2.log" plist="$HOME/Library/LaunchAgents/com.$(id -un).$1.plist"
  cat > "$plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$label</string>
    <key>ProgramArguments</key>
    <array>
        <string>$BIN</string>${3:+
        <string>$3</string>}
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <key>ThrottleInterval</key>
    <integer>5</integer>
    <key>ProcessType</key>
    <string>Interactive</string>
    <key>LimitLoadToSessionType</key>
    <string>Aqua</string>
    <key>StandardOutPath</key>
    <string>$log</string>
    <key>StandardErrorPath</key>
    <string>$log</string>
</dict>
</plist>
PLIST
  # Re-register rather than just restart: launchd records the binary it's allowed to run,
  # and refuses a rebuilt one ("Unable to get updated LWCR") until re-registered.
  launchctl bootout "gui/$UID/$label" 2>/dev/null || true
  local attempt
  for attempt in 1 2 3 4 5; do
    sleep 1
    launchctl bootstrap "gui/$UID" "$plist" 2>/dev/null && { echo "started $label"; return 0; }
  done
  echo "couldn't start $label. Try: launchctl bootstrap gui/$UID \"$plist\""
  return 1
}

install_agent checklistwidget checklist-widget
install_agent weeklywidget weekly-widget --weekly
